INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '鮮', NULL, 'xiān', 'ít, hiếm', 'Vs', '這種情況鮮少發生。', 'zhè zhǒng qíng kuàng xiān shǎo fā shēng。', 'Tình huống như thế này hiếm khi xảy ra.', 'dictionary_words', 1606) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '太空', NULL, 'tàikōng', 'vũ trụ', 'N', '科學家正在研究太空中有沒有其他生命。', 'kē xué jiā zhèng zài yán jiū tài kōng zhōng yǒu méi yǒu qí tā shēng mìng。', 'Các nhà khoa học đang nghiên cứu xem trong vũ trụ có sự sống khác hay không.', 'dictionary_words', 1607) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '攤子', NULL, 'tānzi', 'sạp, quầy (hàng)', 'N', '夜市裡有一個賣小吃的攤子，生意很好。', 'yè shì lǐ yǒu yí gè mài xiǎo chī de tān zi, shēng yì hěn hǎo。', 'Trong chợ đêm có một sạp bán đồ ăn vặt, buôn bán rất tốt.', 'dictionary_words', 1608) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '毯子', NULL, 'tănzi', 'tấm thảm', 'N', '客廳地上鋪了一條漂亮的毯子。', 'kè tīng dì shang pū le yì tiáo piào liang de tǎn zi。', 'Trên sàn phòng khách trải một tấm thảm đẹp.', 'dictionary_words', 1609) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '探', NULL, 'tàn', 'thăm dò', 'V', '警察先派人去探一下那棟房子的情況。', 'jǐng chá xiān pài rén qù tàn yí xià nà dòng fáng zi de qíng kuàng。', 'Cảnh sát trước tiên cử người đi thăm dò tình hình căn nhà đó.', 'dictionary_words', 1610) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '探親', NULL, 'tànqīn', 'thăm người thân', 'V-sep', '過年的時候，他特地回老家探親。', 'guò nián de shí hou, tā tè dì huí lǎo jiā tàn qīn。', 'Vào dịp Tết, anh ấy đặc biệt về quê để thăm người thân.', 'dictionary_words', 1611) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '趟', NULL, 'tàng', 'lần, chuyến', 'M', '我明天要去一趟銀行辦事情。', 'wǒ míng tiān yào qù yí tàng yín háng bàn shì qing。', 'Ngày mai tôi phải đi một chuyến đến ngân hàng để giải quyết việc.', 'dictionary_words', 1612) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '燙', NULL, 'tàng', 'phỏng, bỏng', 'V', '小心別被熱湯燙到手。', 'xiǎo xīn bié bèi rè tāng tàng dào shǒu。', 'Cẩn thận kẻo bị canh nóng làm bỏng tay.', 'dictionary_words', 1613) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '燙', NULL, 'tàng', 'là, ủi', 'Vs', '這件襯衫皺了，要拿去燙一下。', 'zhè jiàn chèn shān zhòu le, yào ná qù tàng yí xià。', 'Cái áo sơ mi này bị nhăn rồi, phải đem đi ủi một chút.', 'dictionary_words', 1614) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '掏', NULL, 'tāo', 'móc, đào', 'V', '他從口袋裡掏出一把鑰匙。', 'tā cóng kǒu dài lǐ tāo chū yì bǎ yào shi。', 'Anh ấy móc từ trong túi ra một chùm chìa khóa.', 'dictionary_words', 1615) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '逃', NULL, 'táo', 'trốn chạy', 'Vi', '小偷一看到警察就拔腿就逃。', 'xiǎo tōu yí kàn dào jǐng chá jiù bá tuǐ jiù táo。', 'Tên trộm vừa nhìn thấy cảnh sát liền vội vàng bỏ chạy.', 'dictionary_words', 1616) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '逃走', NULL, 'táozŏu', 'chạy trốn', 'Vp', '犯人趁大家不注意的時候偷偷逃走了。', 'fàn rén chèn dà jiā bú zhù yì de shí hou tōu tōu táo zǒu le。', 'Tên phạm nhân đã lén lút chạy trốn khi mọi người không để ý.', 'dictionary_words', 1617) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '淘氣', NULL, 'táoqì', 'tinh nghịch', 'Vs', '這個小孩很淘氣，常常把家裡弄得亂七八糟。', 'zhè ge xiǎo hái hěn táo qì, cháng cháng bǎ jiā lǐ nòng de luàn qī bā zāo。', 'Đứa trẻ này rất nghịch ngợm, thường xuyên làm nhà cửa lộn xộn.', 'dictionary_words', 1618) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '桃子', NULL, 'táozi', 'quả đào', 'N', '這顆桃子又甜又多汁，很好吃。', 'zhè kē táo zi yòu tián yòu duō zhī, hěn hǎo chī。', 'Quả đào này vừa ngọt vừa nhiều nước, rất ngon.', 'dictionary_words', 1619) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '討', NULL, 'tăo', 'thỉnh cầu, xin', 'V', '他向老闆討了幾天假，回家陪父母。', 'tā xiàng lǎo bǎn tǎo le jǐ tiān jià, huí jiā péi fù mǔ。', 'Anh ấy xin ông chủ mấy ngày nghỉ để về nhà ở bên bố mẹ.', 'dictionary_words', 1620) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '套', NULL, 'tào', 'bộ', 'M', '我上個月買了一套新家具。', 'wǒ shàng ge yuè mǎi le yí tào xīn jiā jù。', 'Tháng trước tôi mua một bộ nội thất mới.', 'dictionary_words', 1621) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '套', NULL, 'tào', 'trùm ngoài, bọc ngoài', 'V', '下雨了，他趕緊把塑膠袋套在背包上。', 'xià yǔ le, tā gǎn jǐn bǎ sù jiāo dài tào zài bēi bāo shàng。', 'Trời mưa rồi, anh ấy vội vàng trùm túi nilon lên ba lô.', 'dictionary_words', 1622) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '特別', NULL, 'tèbié', 'đặc biệt', 'Adv', '今天的考試特別難，大家都寫不完。', 'jīn tiān de kǎo shì tè bié nán, dà jiā dōu xiě bù wán。', 'Bài thi hôm nay đặc biệt khó, mọi người đều không làm kịp hết.', 'dictionary_words', 1623) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '特點', NULL, 'tèdiăn', 'đặc điểm', 'N', '這座城市最大的特點就是交通方便。', 'zhè zuò chéng shì zuì dà de tè diǎn jiù shì jiāo tōng fāng biàn。', 'Đặc điểm lớn nhất của thành phố này chính là giao thông thuận tiện.', 'dictionary_words', 1624) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '提起', NULL, 'tíqĭ', 'nhắc nhở', 'V', '一提起那場車禍，他就忍不住掉眼淚。', 'yì tí qǐ nà chǎng chē huò, tā jiù rěn bú zhù diào yǎn lèi。', 'Vừa nhắc đến vụ tai nạn xe đó, anh ấy liền không kìm được nước mắt.', 'dictionary_words', 1625) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '提前', NULL, 'tíqián', 'trước thời hạn', 'Vp', '因為颱風要來，會議提前到明天舉行。', 'yīn wèi tái fēng yào lái, huì yì tí qián dào míng tiān jǔ xíng。', 'Vì bão sắp đến nên cuộc họp được tổ chức sớm hơn, dời lên ngày mai.', 'dictionary_words', 1626) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '提醒', NULL, 'tíxĭng', 'nhắc nhở', 'V', '謝謝你提醒我，不然我差點忘記帶護照。', 'xiè xie nǐ tí xǐng wǒ, bù rán wǒ chà diǎn wàng jì dài hù zhào。', 'Cảm ơn bạn đã nhắc tôi, không thì tôi suýt quên mang hộ chiếu.', 'dictionary_words', 1627) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '提早', NULL, 'tízăo', 'sớm hơn, trước thời hạn', 'Vp', '為了避開塞車，我們決定提早出發。', 'wèi le bì kāi sāi chē, wǒ men jué dìng tí zǎo chū fā。', 'Để tránh kẹt xe, chúng tôi quyết định xuất phát sớm hơn.', 'dictionary_words', 1628) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '題', NULL, 'tí', 'đề mục', 'M', '這份考卷一共有三十題。', 'zhè fèn kǎo juàn yí gòng yǒu sān shí tí。', 'Bài thi này tổng cộng có ba mươi câu.', 'dictionary_words', 1629) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '體溫', NULL, 'tĭwēn', 'nhiệt độ cơ thể', 'N', '護士幫病人量了體溫，發現有點發燒。', 'hù shi bāng bìng rén liáng le tǐ wēn, fā xiàn yǒu diǎn fā shāo。', 'Y tá đo thân nhiệt cho bệnh nhân và phát hiện hơi sốt.', 'dictionary_words', 1630) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '體驗', NULL, 'tǐyàn', 'trải nghiệm', 'V', '這次旅行讓我體驗到不同的文化。', 'zhè cì lǚ xíng ràng wǒ tǐ yàn dào bù tóng de wén huà。', 'Chuyến du lịch này cho tôi trải nghiệm những nền văn hóa khác nhau.', 'dictionary_words', 1631) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '天才', NULL, 'tiāncái', 'thiên tài', 'N', '大家都說他是音樂天才，五歲就會作曲。', 'dà jiā dōu shuō tā shì yīn yuè tiān cái, wǔ suì jiù huì zuò qǔ。', 'Mọi người đều nói anh ấy là thiên tài âm nhạc, mới năm tuổi đã biết sáng tác.', 'dictionary_words', 1632) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '天空', NULL, 'tiānkōng', 'bầu trời', 'N', '傍晚的天空被染成一片橘紅色。', 'bàng wǎn de tiān kōng bèi rǎn chéng yí piàn jú hóng sè。', 'Bầu trời lúc chiều tà nhuộm thành một màu cam đỏ.', 'dictionary_words', 1633) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '天然', NULL, 'tiānrán', 'thiên nhiên', 'Vs', '這種化妝品標榜使用天然的成分。', 'zhè zhǒng huà zhuāng pǐn biāo bǎng shǐ yòng tiān rán de chéng fèn。', 'Loại mỹ phẩm này quảng cáo là sử dụng thành phần tự nhiên.', 'dictionary_words', 1634) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '天真', NULL, 'tiānzhēn', 'ngây thơ', 'Vs', '她的想法太天真了，現實沒有那麼簡單。', 'tā de xiǎng fǎ tài tiān zhēn le, xiàn shí méi yǒu nà me jiǎn dān。', 'Suy nghĩ của cô ấy quá ngây thơ, thực tế không đơn giản như vậy.', 'dictionary_words', 1635) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '天主教', NULL, 'tiānzhŭjiào', 'đạo Thiên Chúa', 'N', '他的家庭世代都信仰天主教。', 'tā de jiā tíng shì dài dōu xìn yǎng tiān zhǔ jiào。', 'Gia đình anh ấy nhiều đời đều theo đạo Thiên Chúa.', 'dictionary_words', 1636) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '田野', NULL, 'tiányě', 'đồng ruộng', 'N', '火車經過鄉下，窗外是一片綠色的田野。', 'huǒ chē jīng guò xiāng xià, chuāng wài shì yí piàn lǜ sè de tián yě。', 'Tàu hỏa chạy qua vùng quê, ngoài cửa sổ là một cánh đồng xanh mướt.', 'dictionary_words', 1637) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '挑', NULL, 'tiāo', 'khều, khêu', 'V', '媽媽正在市場裡仔細挑水果。', 'mā ma zhèng zài shì chǎng lǐ zǐ xì tiāo shuǐ guǒ。', 'Mẹ đang cẩn thận chọn trái cây trong chợ.', 'dictionary_words', 1638) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '挑選', NULL, 'tiāoxuăn', 'chọn lựa', 'V', '挑選禮物的時候，要考慮對方喜歡什麼。', 'tiāo xuǎn lǐ wù de shí hou, yào kǎo lǜ duì fāng xǐ huan shén me。', 'Khi chọn quà, phải suy nghĩ xem đối phương thích gì.', 'dictionary_words', 1639) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '條約', NULL, 'tiáoyuē', 'điều ước', 'N', '兩國簽署了一份貿易條約。', 'liǎng guó qiān shǔ le yí fèn mào yì tiáo yuē。', 'Hai nước đã ký kết một hiệp ước thương mại.', 'dictionary_words', 1640) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '調', NULL, 'tiáo', 'điều động, phân phối', 'V', '公司決定把他調到台北分店工作。', 'gōng sī jué dìng bǎ tā tiáo dào tái běi fēn diàn gōng zuò。', 'Công ty quyết định điều anh ấy đến làm việc tại chi nhánh Đài Bắc.', 'dictionary_words', 1641) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '調整', NULL, 'tiáozhěng', 'điều chỉnh', 'V', '老師根據學生的程度調整了上課進度。', 'lǎo shī gēn jù xué shēng de chéng dù tiáo zhěng le shàng kè jìn dù。', 'Giáo viên đã điều chỉnh tiến độ dạy học dựa theo trình độ học sinh.', 'dictionary_words', 1642) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '跳高', NULL, 'tiàogāo', 'nhảy cao', 'Vi', '他從小練習跳高，運動會常常拿第一名。', 'tā cóng xiǎo liàn xí tiào gāo, yùn dòng huì cháng cháng ná dì yī míng。', 'Anh ấy tập nhảy cao từ nhỏ, hội thao thường xuyên đứng nhất.', 'dictionary_words', 1643) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '跳遠', NULL, 'tiàoyuăn', 'nhảy xa', 'Vi', '體育課今天要測驗跳遠。', 'tǐ yù kè jīn tiān yào cè yàn tiào yuǎn。', 'Tiết thể dục hôm nay sẽ kiểm tra môn nhảy xa.', 'dictionary_words', 1644) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '貼心', NULL, 'tiēxīn', 'thân mật', 'Vs', '這個服務生很貼心，主動幫客人拉椅子。', 'zhè ge fú wù shēng hěn tiē xīn, zhǔ dòng bāng kè rén lā yǐ zi。', 'Người phục vụ này rất chu đáo, chủ động kéo ghế giúp khách.', 'dictionary_words', 1645) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '停止', NULL, 'tíngzhĭ', 'đình chỉ', 'Vpt', '因為下大雨，比賽只好暫時停止。', 'yīn wèi xià dà yǔ, bǐ sài zhǐ hǎo zàn shí tíng zhǐ。', 'Vì trời mưa to nên trận đấu đành phải tạm dừng.', 'dictionary_words', 1646) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '挺', NULL, 'tĭng', 'thẳng, ngay thẳng', 'V', '軍人站得挺直，一動也不動。', 'jūn rén zhàn de tǐng zhí, yí dòng yě bú dòng。', 'Người lính đứng thẳng người, không nhúc nhích một chút nào.', 'dictionary_words', 1647) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '挺', NULL, 'tĭng', 'ưỡn, ngửa ra', 'Vs', '孕婦挺著肚子，走路有點辛苦。', 'yùn fù tǐng zhe dù zi, zǒu lù yǒu diǎn xīn kǔ。', 'Người phụ nữ mang thai ưỡn bụng đi lại, có chút vất vả.', 'dictionary_words', 1648) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '通', NULL, 'tōng', 'hồi, trận', 'M', '昨天半夜他突然打了一通電話給我。', 'zuó tiān bàn yè tā tú rán dǎ le yì tōng diàn huà gěi wǒ。', 'Nửa đêm hôm qua anh ấy đột nhiên gọi cho tôi một cuộc điện thoại.', 'dictionary_words', 1649) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '通', NULL, 'tōng', 'thông', 'Vs', '這條路前面施工，不通了。', 'zhè tiáo lù qián miàn shī gōng, bù tōng le。', 'Con đường này phía trước đang thi công, không thông được nữa.', 'dictionary_words', 1650) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '通常', NULL, 'tōngcháng', 'thông thường', 'Adv', '我通常早上七點起床。', 'wǒ tōng cháng zǎo shang qī diǎn qǐ chuáng。', 'Tôi thường thức dậy lúc bảy giờ sáng.', 'dictionary_words', 1651) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '通過', NULL, 'tōngguò', 'thông qua', 'V', '這個法案已經在國會通過了。', 'zhè ge fǎ àn yǐ jīng zài guó huì tōng guò le。', 'Dự luật này đã được thông qua tại quốc hội.', 'dictionary_words', 1652) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '通信', NULL, 'tōngxìn', 'thư từ qua lại', 'V-sep', '他們分開後一直靠寫信通信。', 'tā men fēn kāi hòu yì zhí kào xiě xìn tōng xìn。', 'Sau khi chia tay, họ vẫn liên lạc thư từ với nhau.', 'dictionary_words', 1653) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '同', NULL, 'tóng', 'giống nhau', 'Adv', '我們同住一間宿舍，感情很好。', 'wǒ men tóng zhù yì jiān sù shè, gǎn qíng hěn hǎo。', 'Chúng tôi cùng ở chung một ký túc xá, tình cảm rất tốt.', 'dictionary_words', 1654) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '同', NULL, 'tóng', 'cùng nhau', 'Vs', '大家意見不同，吵了起來。', 'dà jiā yì jiàn bù tóng, chǎo le qǐ lái。', 'Mọi người ý kiến không giống nhau nên đã cãi nhau.', 'dictionary_words', 1655) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '同胞', NULL, 'tóngbāo', 'anh chị em ruột', 'N', '演講的最後，他呼籲海外同胞支持家鄉的建設。', 'yǎn jiǎng de zuì hòu, tā hū yù hǎi wài tóng bāo zhī chí jiā xiāng de jiàn shè。', 'Cuối bài diễn thuyết, ông kêu gọi đồng bào ở nước ngoài ủng hộ xây dựng quê hương.', 'dictionary_words', 1656) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '同志', NULL, 'tóngzhì', 'đồng chí', 'N', '這部電影描述了一對同志伴侶的生活。', 'zhè bù diàn yǐng miáo shù le yí duì tóng zhì bàn lǚ de shēng huó。', 'Bộ phim này miêu tả cuộc sống của một cặp đôi đồng tính.', 'dictionary_words', 1657) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '銅', NULL, 'tóng', 'đồng (kim loại)', 'N', '這座雕像是用銅做的。', 'zhè zuò diāo xiàng shì yòng tóng zuò de。', 'Bức tượng này được làm bằng đồng.', 'dictionary_words', 1658) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '桶', NULL, 'tǒng', 'thùng', 'M', '他提了一桶水去澆花。', 'tā tí le yì tǒng shuǐ qù jiāo huā。', 'Anh ấy xách một thùng nước đi tưới hoa.', 'dictionary_words', 1659) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '統計', NULL, 'tǒngjì', 'thống kê', 'V', '根據統計，今年遊客人數增加了一倍。', 'gēn jù tǒng jì, jīn nián yóu kè rén shù zēng jiā le yí bèi。', 'Theo thống kê, số lượng du khách năm nay đã tăng gấp đôi.', 'dictionary_words', 1660) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '統一', NULL, 'tǒngyī', 'thống nhất', 'Vs', '公司要求所有員工穿統一的制服。', 'gōng sī yāo qiú suǒ yǒu yuán gōng chuān tǒng yī de zhì fú。', 'Công ty yêu cầu tất cả nhân viên mặc đồng phục thống nhất.', 'dictionary_words', 1661) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '統治', NULL, 'tǒngzhì', 'thống trị', 'V', '這個地區曾經被外國統治了好幾十年。', 'zhè ge dì qū céng jīng bèi wài guó tǒng zhì le hǎo jǐ shí nián。', 'Khu vực này từng bị nước ngoài thống trị mấy chục năm.', 'dictionary_words', 1662) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '痛快', NULL, 'tòngkuai', 'vui vẻ', 'Vs', '考完試後，我們去唱歌唱得很痛快。', 'kǎo wán shì hòu, wǒ men qù chàng gē chàng de hěn tòng kuai。', 'Sau khi thi xong, chúng tôi đi hát rất thỏa thích.', 'dictionary_words', 1663) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '偷/偷偷', NULL, 'tōu/tōutōu', 'vụng trộm, lén lút', 'Adv', '弟弟偷偷把我的蛋糕吃掉了。', 'dì di tōu tōu bǎ wǒ de dàn gāo chī diào le。', 'Em trai lén lút ăn mất bánh kem của tôi.', 'dictionary_words', 1664) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '頭', NULL, 'tóu', 'đầu', 'M', '農場裡養了十頭牛。', 'nóng chǎng lǐ yǎng le shí tóu niú。', 'Trong trang trại nuôi mười con bò.', 'dictionary_words', 1665) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '投票', NULL, 'tóupiào', 'bỏ phiếu', 'V-sep', '選舉那天，大家都去投票。', 'xuǎn jǔ nà tiān, dà jiā dōu qù tóu piào。', 'Ngày bầu cử, mọi người đều đi bỏ phiếu.', 'dictionary_words', 1666) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '投入', NULL, 'tóurù', 'đi vào', 'V', '政府投入大量資金改善交通建設。', 'zhèng fǔ tóu rù dà liàng zī jīn gǎi shàn jiāo tōng jiàn shè。', 'Chính phủ đầu tư một lượng lớn vốn để cải thiện xây dựng giao thông.', 'dictionary_words', 1667) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '投降', NULL, 'tóuxiáng', 'đầu hàng', 'Vi', '敵軍彈盡糧絕，最後只好投降。', 'dí jūn dàn jìn liáng jué, zuì hòu zhǐ hǎo tóu xiáng。', 'Quân địch hết đạn hết lương, cuối cùng đành phải đầu hàng.', 'dictionary_words', 1668) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '透', NULL, 'tòu', 'thẩm thấu, thấm qua', 'Vs', '雨太大了，鞋子都濕透了。', 'yǔ tài dà le, xié zi dōu shī tòu le。', 'Mưa to quá, giày đều ướt sũng cả.', 'dictionary_words', 1669) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '禿', NULL, 'tū', 'trọc, trụi', 'Vs', '爺爺年紀大了，頭髮都禿了。', 'yé ye nián jì dà le, tóu fa dōu tū le。', 'Ông nội tuổi đã cao, tóc đã hói cả.', 'dictionary_words', 1670) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '突出', NULL, 'túchū', 'xông ra, nhô ra', 'Vs', '他在這次比賽中表現得特別突出。', 'tā zài zhè cì bǐ sài zhōng biǎo xiàn de tè bié tū chū。', 'Anh ấy thể hiện đặc biệt nổi bật trong cuộc thi lần này.', 'dictionary_words', 1671) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '突破', NULL, 'túpò', 'sự đột phá', 'N', '這項研究是醫學史上的重大突破。', 'zhè xiàng yán jiū shì yī xué shǐ shàng de zhòng dà tū pò。', 'Nghiên cứu này là một đột phá quan trọng trong lịch sử y học.', 'dictionary_words', 1672) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '突破', NULL, 'túpò', 'đột phá', 'V', '他終於突破了自己的紀錄。', 'tā zhōng yú tū pò le zì jǐ de jì lù。', 'Cuối cùng anh ấy đã phá được kỷ lục của chính mình.', 'dictionary_words', 1673) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '途徑', NULL, 'tújìng', 'con đường, đường lối', 'N', '學好語言最有效的途徑就是多練習說。', 'xué hǎo yǔ yán zuì yǒu xiào de tú jìng jiù shì duō liàn xí shuō。', 'Con đường hiệu quả nhất để học tốt ngôn ngữ chính là luyện nói nhiều.', 'dictionary_words', 1674) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '圖書', NULL, 'túshū', 'con dấu, con mộc', 'N', '這間圖書館收藏了許多珍貴的圖書。', 'zhè jiān tú shū guǎn shōu cáng le xǔ duō zhēn guì de tú shū。', 'Thư viện này lưu giữ rất nhiều sách quý giá.', 'dictionary_words', 1675) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '圖章', NULL, 'túzhāng', 'dấu ấn, dấu mộc', 'N', '領包裹的時候要蓋圖章。', 'lǐng bāo guǒ de shí hou yào gài tú zhāng。', 'Khi nhận bưu kiện phải đóng dấu.', 'dictionary_words', 1676) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '吐', NULL, 'tŭ', 'nhổ, nhả', 'V', '請不要隨地吐痰。', 'qǐng bú yào suí dì tǔ tán。', 'Xin đừng khạc nhổ bừa bãi.', 'dictionary_words', 1677) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '團', NULL, 'tuán', 'hình tròn', 'M', '桌上放了一團毛線。', 'zhuō shang fàng le yì tuán máo xiàn。', 'Trên bàn đặt một cuộn len.', 'dictionary_words', 1678) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '團結', NULL, 'tuánjié', 'đoàn kết', 'Vs', '全班同學團結一心，終於贏了比賽。', 'quán bān tóng xué tuán jié yì xīn, zhōng yú yíng le bǐ sài。', 'Cả lớp đoàn kết một lòng, cuối cùng đã giành chiến thắng.', 'dictionary_words', 1679) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '推動', NULL, 'tuīdòng', 'thúc đẩy', 'V', '政府積極推動環保政策。', 'zhèng fǔ jī jí tuī dòng huán bǎo zhèng cè。', 'Chính phủ tích cực thúc đẩy chính sách bảo vệ môi trường.', 'dictionary_words', 1680) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '推翻', NULL, 'tuīfān', 'lật đổ', 'V', '人民起義，推翻了腐敗的政權。', 'rén mín qǐ yì, tuī fān le fǔ bài de zhèng quán。', 'Nhân dân khởi nghĩa, lật đổ chính quyền tham nhũng.', 'dictionary_words', 1681) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '推廣', NULL, 'tuīguăng', 'mở rộng', 'V', '學校正在推廣閱讀活動。', 'xué xiào zhèng zài tuī guǎng yuè dú huó dòng。', 'Trường học đang quảng bá hoạt động đọc sách.', 'dictionary_words', 1682) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '退', NULL, 'tuì', 'lui, lùi', 'Vpt', '他嚇得往後退了一步。', 'tā xià de wǎng hòu tuì le yí bù。', 'Anh ấy sợ đến mức lùi lại một bước.', 'dictionary_words', 1683) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '退出', NULL, 'tuìchū', 'rút khỏi', 'Vpt', '因為受傷，他決定退出這次比賽。', 'yīn wèi shòu shāng, tā jué dìng tuì chū zhè cì bǐ sài。', 'Vì bị thương, anh ấy quyết định rút khỏi cuộc thi lần này.', 'dictionary_words', 1684) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '退回', NULL, 'tuìhuí', 'trả lại', 'Vpt', '這件衣服尺寸不合，我想退回去。', 'zhè jiàn yī fu chǐ cùn bù hé, wǒ xiǎng tuì huí qù。', 'Chiếc áo này không vừa size, tôi muốn trả lại.', 'dictionary_words', 1685) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '吞', NULL, 'tūn', 'nuốt, ngốn', 'V', '藥丸太大了，他吞不下去。', 'yào wán tài dà le, tā tūn bú xià qu。', 'Viên thuốc to quá, anh ấy không nuốt được.', 'dictionary_words', 1686) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拖', NULL, 'tuō', 'kéo, dắt', 'V', '他把沉重的行李箱拖到車站。', 'tā bǎ chén zhòng de xíng li xiāng tuō dào chē zhàn。', 'Anh ấy kéo chiếc vali nặng đến bến xe.', 'dictionary_words', 1687) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
