INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '托兒所', NULL, 'tuōérsuŏ', 'nhà trẻ', 'N', '這家托兒所離我家很近，很方便。', 'zhè jiā tuō ér suǒ lí wǒ jiā hěn jìn, hěn fāng biàn。', 'Nhà trẻ này gần nhà tôi, rất tiện lợi.', 'dictionary_words', 1689) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '脫離', NULL, 'tuōlí', 'thoát ly', 'V', '病人已經脫離危險期了。', 'bìng rén yǐ jīng tuō lí wéi xiǎn qī le。', 'Bệnh nhân đã thoát khỏi giai đoạn nguy hiểm rồi.', 'dictionary_words', 1690) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '妥善', NULL, 'tuŏshàn', 'ổn thỏa', 'Vs', '這件事情已經得到妥善的處理。', 'zhè jiàn shì qing yǐ jīng dé dào tuǒ shàn de chǔ lǐ。', 'Việc này đã được xử lý ổn thỏa.', 'dictionary_words', 1691) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '妥協', NULL, 'tuŏxié', 'thỏa hiệp', 'Vi', '為了和平，雙方最後願意妥協。', 'wèi le hé píng, shuāng fāng zuì hòu yuàn yì tuǒ xié。', 'Vì hòa bình, cuối cùng hai bên sẵn lòng thỏa hiệp.', 'dictionary_words', 1692) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
