INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '歪', NULL, 'wāi', 'nghiêng, lệch', 'Vs', '這幅畫掛歪了，幫我扶正一下。', 'zhè fú huà guà wāi le, bāng wǒ fú zhèng yí xià。', 'Bức tranh này treo bị lệch rồi, giúp tôi chỉnh lại cho ngay.', 'dictionary_words', 1694) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外部', NULL, 'wàibù', 'phần ngoài, vẻ ngoài', 'N', '這台機器的外部看起來沒什麼問題。', 'zhè tái jī qì de wài bù kàn qǐ lái méi shén me wèn tí。', 'Phần bên ngoài của cái máy này nhìn có vẻ không có vấn đề gì.', 'dictionary_words', 1695) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外出', NULL, 'wàichū', 'đi chơi', 'Vi', '爸爸外出開會，晚上才會回來。', 'bà ba wài chū kāi huì, wǎn shang cái huì huí lai。', 'Bố đi ra ngoài họp, tối mới về.', 'dictionary_words', 1696) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外地', NULL, 'wàidì', 'nơi khác, vùng khác', 'N', '他是外地人，來這裡工作才兩年。', 'tā shì wài dì rén, lái zhè lǐ gōng zuò cái liǎng nián。', 'Anh ấy là người từ nơi khác đến, mới làm việc ở đây được hai năm.', 'dictionary_words', 1697) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外觀', NULL, 'wàiguān', 'bề ngoài', 'N', '這款手機外觀設計得很時尚。', 'zhè kuǎn shǒu jī wài guān shè jì de hěn shí shàng。', 'Mẫu điện thoại này có thiết kế bề ngoài rất thời trang.', 'dictionary_words', 1698) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外行', NULL, 'wàiháng', 'không chuyên môn, ngoài nghề', 'Vs', '修理電腦我完全外行，還是找專家吧。', 'xiū lǐ diàn nǎo wǒ wán quán wài háng, hái shi zhǎo zhuān jiā ba。', 'Sửa máy tính thì tôi hoàn toàn không rành, thôi tìm chuyên gia đi.', 'dictionary_words', 1699) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外匯', NULL, 'wàihuì', 'ngoại hối', 'N', '出國前記得先換一些外匯。', 'chū guó qián jì de xiān huàn yì xiē wài huì。', 'Trước khi ra nước ngoài nhớ đổi một ít ngoại tệ.', 'dictionary_words', 1700) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外交', NULL, 'wàijiāo', 'ngoại giao', 'N', '兩國之間的外交關係最近改善了不少。', 'liǎng guó zhī jiān de wài jiāo guān xi zuì jìn gǎi shàn le bù shǎo。', 'Quan hệ ngoại giao giữa hai nước gần đây đã được cải thiện nhiều.', 'dictionary_words', 1701) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外界', NULL, 'wàijiè', 'bên ngoài', 'N', '這件事引起了外界很大的關注。', 'zhè jiàn shì yǐn qǐ le wài jiè hěn dà de guān zhù。', 'Việc này đã thu hút sự quan tâm rất lớn từ bên ngoài.', 'dictionary_words', 1702) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外科', NULL, 'wàikē', 'ngoại khoa', 'N', '他因為骨折，被送到外科開刀。', 'tā yīn wèi gǔ zhé, bèi sòng dào wài kē kāi dāo。', 'Vì bị gãy xương, anh ấy được đưa đến khoa ngoại để phẫu thuật.', 'dictionary_words', 1703) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '外頭', NULL, 'wàitou', 'bề ngoài', 'N', '外頭在下雨，你出門記得帶傘。', 'wài tou zài xià yǔ, nǐ chū mén jì de dài sǎn。', 'Bên ngoài đang mưa, ra ngoài nhớ mang theo ô.', 'dictionary_words', 1704) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '彎', NULL, 'wān', 'cong, ngoằn ngoèo', 'Vs', '這條山路又彎又窄，開車要小心。', 'zhè tiáo shān lù yòu wān yòu zhǎi, kāi chē yào xiǎo xīn。', 'Con đường núi này vừa quanh co vừa hẹp, lái xe phải cẩn thận.', 'dictionary_words', 1705) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '彎腰', NULL, 'wānyāo', 'cúi gập người', 'V-sep', '他彎腰撿起掉在地上的錢包。', 'tā wān yāo jiǎn qǐ diào zài dì shang de qián bāo。', 'Anh ấy cúi người nhặt lên chiếc ví rơi trên đất.', 'dictionary_words', 1706) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '先進', NULL, 'xiānjìn', 'tiên tiến', 'Vs', '這家醫院的醫療設備非常先進。', 'zhè jiā yī yuàn de yī liáo shè bèi fēi cháng xiān jìn。', 'Thiết bị y tế của bệnh viện này rất tiên tiến.', 'dictionary_words', 1707) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '完畢', NULL, 'wánbì', 'hoàn tất', 'Vp', '手術完畢後，病人被送回病房休息。', 'shǒu shù wán bì hòu, bìng rén bèi sòng huí bìng fáng xiū xi。', 'Sau khi phẫu thuật hoàn tất, bệnh nhân được đưa về phòng bệnh nghỉ ngơi.', 'dictionary_words', 1708) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '完善', NULL, 'wánshàn', 'hoàn thiện', 'Vs', '這套系統的功能還不夠完善。', 'zhè tào xì tǒng de gōng néng hái bú gòu wán shàn。', 'Chức năng của hệ thống này vẫn chưa đủ hoàn thiện.', 'dictionary_words', 1709) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '完整', NULL, 'wánzhěng', 'toàn vẹn', 'Vs', '這是一份完整的報告，資料非常齊全。', 'zhè shì yí fèn wán zhěng de bào gào, zī liào fēi cháng qí quán。', 'Đây là một bản báo cáo hoàn chỉnh, tư liệu rất đầy đủ.', 'dictionary_words', 1710) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '玩笑', NULL, 'wánxiào', 'vui đùa', 'N', '別生氣，我只是開個玩笑而已。', 'bié shēng qì, wǒ zhǐ shì kāi ge wán xiào ér yǐ。', 'Đừng giận, tôi chỉ đùa một chút thôi.', 'dictionary_words', 1711) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '晚輩', NULL, 'wănbèi', 'thế hệ sau, hậu bối', 'N', '身為晚輩，我們應該尊敬長輩。', 'shēn wéi wǎn bèi, wǒ men yīng gāi zūn jìng zhǎng bèi。', 'Là hàng con cháu, chúng ta nên tôn kính người lớn tuổi.', 'dictionary_words', 1712) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '往', NULL, 'wăng', 'hướng về', 'V', '這班公車是往台北車站的方向。', 'zhè bān gōng chē shì wǎng tái běi chē zhàn de fāng xiàng。', 'Chuyến xe buýt này đi theo hướng về ga Đài Bắc.', 'dictionary_words', 1713) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '望', NULL, 'wàng', 'trông, nhìn (xa)', 'V', '她站在窗邊，望著遠方發呆。', 'tā zhàn zài chuāng biān, wàng zhe yuǎn fāng fā dāi。', 'Cô ấy đứng bên cửa sổ, nhìn về phía xa mà thẫn thờ.', 'dictionary_words', 1714) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '威脅', NULL, 'wēixié', 'sự uy hiếp', 'N', '環境污染對人類健康造成很大的威脅。', 'huán jìng wū rǎn duì rén lèi jiàn kāng zào chéng hěn dà de wēi xié。', 'Ô nhiễm môi trường gây ra mối đe dọa rất lớn đối với sức khỏe con người.', 'dictionary_words', 1715) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '威脅', NULL, 'wēixié', 'uy hiếp', 'V', '歹徒拿刀威脅店員交出現金。', 'dǎi tú ná dāo wēi xié diàn yuán jiāo chū xiàn jīn。', 'Tên côn đồ cầm dao đe dọa nhân viên cửa hàng đưa tiền mặt ra.', 'dictionary_words', 1716) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '圍', NULL, 'wéi', 'vây, bao vây', 'V', '很多人圍在一起看熱鬧。', 'hěn duō rén wéi zài yì qǐ kàn rè nao。', 'Rất nhiều người vây quanh nhau xem náo nhiệt.', 'dictionary_words', 1717) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '違反', NULL, 'wéifăn', 'trái với', 'Vst', '闖紅燈是違反交通規則的行為。', 'chuǎng hóng dēng shì wéi fǎn jiāo tōng guī zé de xíng wéi。', 'Vượt đèn đỏ là hành vi vi phạm luật giao thông.', 'dictionary_words', 1718) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '維護', NULL, 'wéihù', 'giữ gìn, bảo vệ', 'V', '大家應該一起維護公共環境的整潔。', 'dà jiā yīng gāi yì qǐ wéi hù gōng gòng huán jìng de zhěng jié。', 'Mọi người nên cùng nhau giữ gìn sự sạch sẽ của môi trường công cộng.', 'dictionary_words', 1719) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '維他命', NULL, 'wéitāmìng', 'vitamin', 'N', '醫生建議我每天補充維他命Ｃ。', 'yī shēng jiàn yì wǒ měi tiān bǔ chōng wéi tā mìng C。', 'Bác sĩ khuyên tôi mỗi ngày nên bổ sung vitamin C.', 'dictionary_words', 1720) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '危機', NULL, 'wéijī', 'nguy cơ', 'N', '這家公司正面臨財務危機。', 'zhè jiā gōng sī zhèng miàn lín cái wù wéi jī。', 'Công ty này đang đối mặt với khủng hoảng tài chính.', 'dictionary_words', 1721) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '為難', NULL, 'wéinán', 'khó xử', 'Vs', '你這樣要求真的讓我很為難。', 'nǐ zhè yàng yāo qiú zhēn de ràng wǒ hěn wéi nán。', 'Bạn yêu cầu như vậy thật sự khiến tôi rất khó xử.', 'dictionary_words', 1722) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '唯一', NULL, 'wéiyī', 'duy nhất', 'Vs-attr', '他是我唯一信任的朋友。', 'tā shì wǒ wéi yī xìn rèn de péng you。', 'Anh ấy là người bạn duy nhất mà tôi tin tưởng.', 'dictionary_words', 1723) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '委託', NULL, 'wěituō', 'ủy thác', 'V', '他委託律師處理這件財產糾紛。', 'tā wěi tuō lǜ shī chǔ lǐ zhè jiàn cái chǎn jiū fēn。', 'Anh ấy ủy thác cho luật sư xử lý vụ tranh chấp tài sản này.', 'dictionary_words', 1724) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '委員', NULL, 'wěiyuán', 'ủy viên', 'N', '她被選為學生會的委員。', 'tā bèi xuǎn wéi xué shēng huì de wěi yuán。', 'Cô ấy được bầu làm ủy viên hội học sinh.', 'dictionary_words', 1725) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '未', NULL, 'wèi', 'vị, chưa, không', 'Adv', '此案至今未破，警方仍在調查。', 'cǐ àn zhì jīn wèi pò, jǐng fāng réng zài diào chá。', 'Vụ án này đến nay vẫn chưa được phá, cảnh sát vẫn đang điều tra.', 'dictionary_words', 1726) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '未婚', NULL, 'wèihūn', 'chưa cưới', 'Vs', '他今年三十五歲，還是未婚。', 'tā jīn nián sān shí wǔ suì, hái shi wèi hūn。', 'Năm nay anh ấy ba mươi lăm tuổi mà vẫn chưa kết hôn.', 'dictionary_words', 1727) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '位於', NULL, 'wèiyú', 'nằm ở', 'Vst', '這家餐廳位於市中心，交通很方便。', 'zhè jiā cān tīng wèi yú shì zhōng xīn, jiāo tōng hěn fāng biàn。', 'Nhà hàng này nằm ở trung tâm thành phố, giao thông rất thuận tiện.', 'dictionary_words', 1728) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '味/味兒', NULL, 'wèi/wèir', 'vị', 'N', '這湯的味兒有點怪，是不是放錯調味料了？', 'zhè tāng de wèir yǒu diǎn guài, shì bu shì fàng cuò tiáo wèi liào le?', 'Vị của món canh này có chút lạ, có phải cho nhầm gia vị không?', 'dictionary_words', 1729) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '為何', NULL, 'wèihé', 'vì sao', 'Adv', '我不明白他為何突然離職。', 'wǒ bù míng bai tā wèi hé tú rán lí zhí。', 'Tôi không hiểu vì sao anh ấy đột nhiên nghỉ việc.', 'dictionary_words', 1730) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '衛生', NULL, 'wèishēng', 'vệ sinh', 'Vs', '這家餐廳的廚房非常衛生。', 'zhè jiā cān tīng de chú fáng fēi cháng wèi shēng。', 'Nhà bếp của nhà hàng này rất sạch sẽ vệ sinh.', 'dictionary_words', 1731) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '衛生紙', NULL, 'wèishēngzhĭ', 'giấy vệ sinh', 'N', '家裡的衛生紙用完了，要再買。', 'jiā lǐ de wèi shēng zhǐ yòng wán le, yào zài mǎi。', 'Giấy vệ sinh trong nhà đã dùng hết, phải mua thêm.', 'dictionary_words', 1732) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '衛星', NULL, 'wèixīng', 'vệ tinh nhân tạo', 'N', '這顆人造衛星負責傳送電視訊號。', 'zhè kē rén zào wèi xīng fù zé chuán sòng diàn shì xùn hào。', 'Vệ tinh nhân tạo này chịu trách nhiệm truyền tín hiệu truyền hình.', 'dictionary_words', 1733) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '慰問', NULL, 'wèiwèn', 'thăm hỏi', 'V', '市長親自到醫院慰問受傷的消防員。', 'shì zhǎng qīn zì dào yī yuàn wèi wèn shòu shāng de xiāo fáng yuán。', 'Thị trưởng đích thân đến bệnh viện thăm hỏi lính cứu hỏa bị thương.', 'dictionary_words', 1734) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '溫和', NULL, 'wēnhé', 'ôn hòa', 'Vs', '他個性溫和，很少跟人起爭執。', 'tā gè xìng wēn hé, hěn shǎo gēn rén qǐ zhēng zhí。', 'Tính cách anh ấy ôn hòa, hiếm khi tranh cãi với người khác.', 'dictionary_words', 1735) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '蚊子', NULL, 'wénzi', 'con muỗi', 'N', '夏天蚊子特別多，要記得噴防蚊液。', 'xià tiān wén zi tè bié duō, yào jì de pēn fáng wén yè。', 'Mùa hè muỗi đặc biệt nhiều, phải nhớ xịt thuốc chống muỗi.', 'dictionary_words', 1736) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '吻', NULL, 'wěn', 'mõm (động vật)', 'N', '這種魚的吻部特別尖長。', 'zhè zhǒng yú de wěn bù tè bié jiān cháng。', 'Phần mõm của loài cá này đặc biệt nhọn và dài.', 'dictionary_words', 1737) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '吻', NULL, 'wěn', 'hôn', 'V', '電影結束前，男主角輕輕吻了女主角一下。', 'diàn yǐng jié shù qián, nán zhǔ jué qīng qīng wěn le nǚ zhǔ jué yí xià。', 'Trước khi phim kết thúc, nam chính khẽ hôn nữ chính một cái.', 'dictionary_words', 1738) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '穩', NULL, 'wěn', 'ổn định, vững', 'Vs', '這張桌子有點不穩，一碰就搖晃。', 'zhè zhāng zhuō zi yǒu diǎn bù wěn, yí pèng jiù yáo huàng。', 'Cái bàn này hơi không vững, vừa chạm vào là lung lay.', 'dictionary_words', 1739) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '握', NULL, 'wò', 'nắm, bắt, cầm', 'V', '兩人第一次見面就熱情地握了手。', 'liǎng rén dì yī cì jiàn miàn jiù rè qíng de wò le shǒu。', 'Hai người gặp nhau lần đầu đã nồng nhiệt bắt tay nhau.', 'dictionary_words', 1740) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '汙/污染', NULL, 'wūrăn', 'ô nhiễm', 'V', '工廠排放廢水，嚴重污染了這條河流。', 'gōng chǎng pái fàng fèi shuǐ, yán zhòng wū rǎn le zhè tiáo hé liú。', 'Nhà máy xả nước thải, làm ô nhiễm nghiêm trọng con sông này.', 'dictionary_words', 1741) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '無可奈何', NULL, 'wúkěnàihé', 'không biết làm thế nào', 'Vs', '面對這樣的結果，他也只能無可奈何地接受。', 'miàn duì zhè yàng de jié guǒ, tā yě zhǐ néng wú kě nài hé de jiē shòu。', 'Đối mặt với kết quả như vậy, anh ấy cũng đành phải bất lực chấp nhận.', 'dictionary_words', 1742) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '無情', NULL, 'wúqíng', 'vô tình', 'Vs', '他對朋友的請求拒絕得十分無情。', 'tā duì péng you de qǐng qiú jù jué de shí fēn wú qíng。', 'Anh ấy từ chối yêu cầu của bạn bè một cách rất vô tình.', 'dictionary_words', 1743) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '無限', NULL, 'wúxiàn', 'vô hạn', 'Vs', '網路資源幾乎是無限的。', 'wǎng lù zī yuán jī hū shì wú xiàn de。', 'Tài nguyên mạng gần như là vô hạn.', 'dictionary_words', 1744) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '無意', NULL, 'wúyì', 'vô ý', 'Vs', '我是無意中聽到他們的談話。', 'wǒ shì wú yì zhōng tīng dào tā men de tán huà。', 'Tôi tình cờ nghe được cuộc trò chuyện của họ.', 'dictionary_words', 1745) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '武器', NULL, 'wŭqì', 'vũ khí', 'N', '警方在嫌犯家中搜出大量武器。', 'jǐng fāng zài xián fàn jiā zhōng sōu chū dà liàng wǔ qì。', 'Cảnh sát lục soát được một lượng lớn vũ khí trong nhà nghi phạm.', 'dictionary_words', 1746) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '武術', NULL, 'wŭshù', 'võ thuật', 'N', '他從小學習中國武術，身手很敏捷。', 'tā cóng xiǎo xué xí zhōng guó wǔ shù, shēn shǒu hěn mǐn jié。', 'Anh ấy học võ thuật Trung Quốc từ nhỏ, thân thủ rất nhanh nhẹn.', 'dictionary_words', 1747) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '舞', NULL, 'wŭ', 'vũ, khiêu vũ', 'N', '他們隨著音樂跳起舞來。', 'tā men suí zhe yīn yuè tiào qǐ wǔ lái。', 'Họ nhảy múa theo tiếng nhạc.', 'dictionary_words', 1748) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '舞蹈', NULL, 'wŭdào', 'điệu múa, vũ đạo', 'N', '她從小學習舞蹈，現在是職業舞者。', 'tā cóng xiǎo xué xí wǔ dào, xiàn zài shì zhí yè wǔ zhě。', 'Cô ấy học múa từ nhỏ, bây giờ là vũ công chuyên nghiệp.', 'dictionary_words', 1749) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '勿', NULL, 'wù', 'chớ, đừng, không nên', 'Adv', '請勿在此拍照。', 'qǐng wù zài cǐ pāi zhào。', 'Xin đừng chụp ảnh ở đây.', 'dictionary_words', 1750) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '物理', NULL, 'wùlĭ', 'vật lý', 'N', '他對物理很有興趣，將來想當科學家。', 'tā duì wù lǐ hěn yǒu xìng qù, jiāng lái xiǎng dāng kē xué jiā。', 'Anh ấy rất hứng thú với vật lý, tương lai muốn làm nhà khoa học.', 'dictionary_words', 1751) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '物質', NULL, 'wùzhí', 'vật chất', 'N', '現代人生活富裕，不只追求物質上的滿足。', 'xiàn dài rén shēng huó fù yù, bù zhǐ zhuī qiú wù zhí shàng de mǎn zú。', 'Người hiện đại sống sung túc, không chỉ theo đuổi sự thỏa mãn về vật chất.', 'dictionary_words', 1752) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '誤', NULL, 'wù', 'lầm, sai', 'Adv', '他誤把鹽當成糖加進咖啡裡。', 'tā wù bǎ yán dāng chéng táng jiā jìn kā fēi lǐ。', 'Anh ấy nhầm cho muối vào cà phê tưởng là đường.', 'dictionary_words', 1753) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '誤', NULL, 'wù', 'lỡ tay', 'Vst', '這個決定誤了公司的商機。', 'zhè ge jué dìng wù le gōng sī de shāng jī。', 'Quyết định này đã làm lỡ cơ hội kinh doanh của công ty.', 'dictionary_words', 1754) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '誤點', NULL, 'wùdiăn', 'trễ giờ', 'Vp', '因為天氣不好，班機誤點了兩個小時。', 'yīn wèi tiān qì bù hǎo, bān jī wù diǎn le liǎng gè xiǎo shí。', 'Vì thời tiết xấu, chuyến bay trễ giờ mất hai tiếng.', 'dictionary_words', 1755) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '誤會', NULL, 'wùhuì', 'hiểu lầm', 'Vst', '你誤會我的意思了，我不是那個意思。', 'nǐ wù huì wǒ de yì si le, wǒ bú shì nà ge yì si。', 'Bạn hiểu lầm ý tôi rồi, tôi không có ý đó.', 'dictionary_words', 1756) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '霧', NULL, 'wù', 'sương mù', 'N', '今天早上霧很大，能見度很低。', 'jīn tiān zǎo shang wù hěn dà, néng jiàn dù hěn dī。', 'Sáng nay sương mù dày đặc, tầm nhìn rất thấp.', 'dictionary_words', 1757) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '西裝', NULL, 'xīzhuāng', 'âu phục', 'N', '他穿著一套深色西裝去面試。', 'tā chuān zhe yí tào shēn sè xī zhuāng qù miàn shì。', 'Anh ấy mặc một bộ com-lê màu tối đi phỏng vấn.', 'dictionary_words', 1758) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '吸', NULL, 'xī', 'hút, hít', 'V', '深深吸一口氣，你會覺得比較放鬆。', 'shēn shēn xī yì kǒu qì, nǐ huì jué de bǐ jiào fàng sōng。', 'Hít thật sâu một hơi, bạn sẽ cảm thấy thư giãn hơn.', 'dictionary_words', 1759) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
