INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '系列', NULL, 'xìliè', 'hàng loạt', 'N', '這是這位作家最新出版的系列小說。', 'zhè shì zhè wèi zuò jiā zuì xīn chū bǎn de xì liè xiǎo shuō。', 'Đây là bộ tiểu thuyết theo series mới nhất mà nhà văn này xuất bản.', 'dictionary_words', 1765) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '細胞', NULL, 'xìbāo', 'tế bào', 'N', '人體是由無數個細胞組成的。', 'rén tǐ shì yóu wú shù gè xì bāo zǔ chéng de。', 'Cơ thể con người được cấu thành từ vô số tế bào.', 'dictionary_words', 1766) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '細節', NULL, 'xìjié', 'tình tiết, chi tiết', 'N', '簽合約之前要仔細確認每一個細節。', 'qiān hé yuē zhī qián yào zǐ xì què rèn měi yí gè xì jié。', 'Trước khi ký hợp đồng phải xác nhận kỹ từng chi tiết.', 'dictionary_words', 1767) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '細菌', NULL, 'xìjùn', 'vi trùng', 'N', '洗手可以有效減少細菌感染。', 'xǐ shǒu kě yǐ yǒu xiào jiǎn shǎo xì jùn gǎn rǎn。', 'Rửa tay có thể giảm hiệu quả sự lây nhiễm vi khuẩn.', 'dictionary_words', 1768) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '細小', NULL, 'xìxiăo', 'nhỏ bé', 'Vs', '這些細小的差異一般人很難發現。', 'zhè xiē xì xiǎo de chā yì yì bān rén hěn nán fā xiàn。', 'Những khác biệt nhỏ bé này người bình thường rất khó phát hiện.', 'dictionary_words', 1769) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '瞎', NULL, 'xiā', 'mù lòa', 'Vp', '他因為一場意外而瞎了一隻眼睛。', 'tā yīn wèi yì chǎng yì wài ér xiā le yì zhī yǎn jing。', 'Anh ấy bị mù một mắt vì một tai nạn.', 'dictionary_words', 1770) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '蝦(子)', NULL, 'xiā(zi)', 'con cóc', 'N', '這道菜用新鮮的蝦子做的，很好吃。', 'zhè dào cài yòng xīn xiān de xiā zi zuò de, hěn hǎo chī。', 'Món ăn này được làm từ tôm tươi, rất ngon.', 'dictionary_words', 1771) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
