INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '現成', NULL, 'xiànchéng', 'sẵn có', 'Vs-attr', '家裡剛好有現成的材料，可以馬上煮飯。', 'jiā lǐ gāng hǎo yǒu xiàn chéng de cái liào, kě yǐ mǎ shàng zhǔ fàn。', 'Trong nhà vừa hay có sẵn nguyên liệu, có thể nấu cơm ngay.', 'dictionary_words', 1787) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
