INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '羨慕', NULL, 'xiànmù', 'hâm mộ', 'Vst', '我很羨慕他能說五種語言。', 'wǒ hěn xiàn mù tā néng shuō wǔ zhǒng yǔ yán。', 'Tôi rất ngưỡng mộ việc anh ấy có thể nói được năm thứ tiếng.', 'dictionary_words', 1789) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '限制', NULL, 'xiànzhì', 'hạn chế', 'V', '這個停車場限制車輛高度不能超過兩公尺。', 'zhè ge tíng chē chǎng xiàn zhì chē liàng gāo dù bù néng chāo guò liǎng gōng chǐ。', 'Bãi đỗ xe này hạn chế chiều cao xe không được vượt quá hai mét.', 'dictionary_words', 1790) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '相', NULL, 'xiāng', 'lẫn nhau, cùng nhau', 'Adv', '這對老夫妻相伴走過五十年。', 'zhè duì lǎo fū qī xiāng bàn zǒu guò wǔ shí nián。', 'Cặp vợ chồng già này đã cùng nhau sát cánh đi qua năm mươi năm.', 'dictionary_words', 1791) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '相處', NULL, 'xiāngchŭ', 'sống chung với nhau', 'Vi', '我跟室友相處得很融洽。', 'wǒ gēn shì yǒu xiāng chǔ de hěn róng qià。', 'Tôi sống chung với bạn cùng phòng rất hòa hợp.', 'dictionary_words', 1792) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
