INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '相親相愛', NULL, 'xiāngqīnxiāngài', 'tương thân tương ái', 'Vs', '這一家人相親相愛，感情非常好。', 'zhè yì jiā rén xiāng qīn xiāng ài, gǎn qíng fēi cháng hǎo。', 'Gia đình này yêu thương nhau, tình cảm rất tốt.', 'dictionary_words', 1795) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '相似', NULL, 'xiāngsì', 'tương tự', 'Vs', '這對雙胞胎長得非常相似。', 'zhè duì shuāng bāo tāi zhǎng de fēi cháng xiāng sì。', 'Cặp song sinh này trông rất giống nhau.', 'dictionary_words', 1796) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '箱', NULL, 'xiāng', 'rương, hòm', 'M', '他訂了一箱蘋果，準備送給朋友。', 'tā dìng le yì xiāng píng guǒ, zhǔn bèi sòng gěi péng you。', 'Anh ấy đặt một thùng táo, chuẩn bị tặng cho bạn bè.', 'dictionary_words', 1797) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '香腸', NULL, 'xiāngcháng', 'lạp xưởng', 'N', '夜市裡烤香腸的味道讓人忍不住想吃。', 'yè shì lǐ kǎo xiāng cháng de wèi dào ràng rén rěn bú zhù xiǎng chī。', 'Mùi xúc xích nướng ở chợ đêm khiến người ta không kìm được muốn ăn.', 'dictionary_words', 1798) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '鄉村', NULL, 'xiāngcūn', 'nông thôn', 'N', '他退休後搬到鄉村過悠閒的生活。', 'tā tuì xiū hòu bān dào xiāng cūn guò yōu xián de shēng huó。', 'Sau khi nghỉ hưu, anh ấy chuyển về nông thôn sống cuộc sống thong thả.', 'dictionary_words', 1799) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '想不到', NULL, 'xiăngbudào', 'không ngờ tới', NULL, '想不到我們會在這種場合重逢。', 'xiǎng bu dào wǒ men huì zài zhè zhǒng chǎng hé chóng féng。', 'Không ngờ chúng ta lại gặp lại nhau trong hoàn cảnh như thế này.', 'dictionary_words', 1800) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '享受', NULL, 'xiăngshòu', 'hưởng thụ, tận hưởng', 'Vst', '週末我喜歡待在家裡享受安靜的時光。', 'zhōu mò wǒ xǐ huan dāi zài jiā lǐ xiǎng shòu ān jìng de shí guāng。', 'Cuối tuần tôi thích ở nhà tận hưởng khoảng thời gian yên tĩnh.', 'dictionary_words', 1801) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
