INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '相片/相片兒', NULL, 'xiàngpiàn/xiàngpi', 'ảnh chụp (người)', 'N', '這張相片是我們全家去年出遊時拍的。', 'zhè zhāng xiàng piàn shì wǒ men quán jiā qù nián chū yóu shí pāi de。', 'Tấm ảnh này là chụp lúc cả gia đình tôi đi chơi năm ngoái.', 'dictionary_words', 1804) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
