INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消費', NULL, 'xiāofèi', 'chi phí', 'N', '這個城市的消費水準比較高。', 'zhè ge chéng shì de xiāo fèi shuǐ zhǔn bǐ jiào gāo。', 'Mức chi tiêu ở thành phố này khá cao.', 'dictionary_words', 1811) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消費', NULL, 'xiāofèi', 'tiêu dùng', 'V', '越來越多人選擇在網路上消費。', 'yuè lái yuè duō rén xuǎn zé zài wǎng lù shàng xiāo fèi。', 'Ngày càng có nhiều người chọn tiêu dùng trên mạng.', 'dictionary_words', 1812) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消化', NULL, 'xiāohuà', 'tiêu hóa', 'V', '吃太快容易造成消化不良。', 'chī tài kuài róng yì zào chéng xiāo huà bù liáng。', 'Ăn quá nhanh dễ gây ra khó tiêu.', 'dictionary_words', 1813) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消極', NULL, 'xiāojí', 'tiêu cực', 'Vs', '失敗後他變得很消極，不想再嘗試。', 'shī bài hòu tā biàn de hěn xiāo jí, bù xiǎng zài cháng shì。', 'Sau khi thất bại, anh ấy trở nên tiêu cực, không muốn thử lại nữa.', 'dictionary_words', 1814) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消滅', NULL, 'xiāomiè', 'tiêu diệt', 'Vpt', '醫生用藥物消滅體內的病菌。', 'yī shēng yòng yào wù xiāo miè tǐ nèi de bìng jūn。', 'Bác sĩ dùng thuốc tiêu diệt vi khuẩn gây bệnh trong cơ thể.', 'dictionary_words', 1815) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '消失', NULL, 'xiāoshī', 'tan biến', 'Vp', '那隻貓突然消失在巷子裡，再也沒出現過。', 'nà zhī māo tú rán xiāo shī zài xiàng zi lǐ, zài yě méi chū xiàn guò。', 'Con mèo đó đột nhiên biến mất trong con hẻm, không bao giờ xuất hiện lại nữa.', 'dictionary_words', 1816) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '銷路', NULL, 'xiāolù', 'nguồn tiêu thụ', 'N', '這款新產品上市後銷路很好。', 'zhè kuǎn xīn chǎn pǐn shàng shì hòu xiāo lù hěn hǎo。', 'Sản phẩm mới này sau khi ra mắt có đầu ra tiêu thụ rất tốt.', 'dictionary_words', 1817) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '銷售', NULL, 'xiāoshòu', 'tiêu thụ', 'V', '這家公司主要銷售電子產品。', 'zhè jiā gōng sī zhǔ yào xiāo shòu diàn zǐ chǎn pǐn。', 'Công ty này chủ yếu bán các sản phẩm điện tử.', 'dictionary_words', 1818) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '小便', NULL, 'xiăobiàn', 'tiểu tiện', 'Vi', '小朋友舉手說他想上廁所小便。', 'xiǎo péng you jǔ shǒu shuō tā xiǎng shàng cè suǒ xiǎo biàn。', 'Đứa trẻ giơ tay nói nó muốn đi vệ sinh tiểu tiện.', 'dictionary_words', 1819) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '愛好', NULL, 'àihào', 'sở thích', 'N', '每個人都應該培養一些自己的愛好。', 'měi gè rén dōu yīng gāi péi yǎng yì xiē zì jǐ de ài hào。', 'Mỗi người đều nên bồi dưỡng cho mình một vài sở thích riêng.', 'dictionary_words', 1820) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '愛護', NULL, 'àihù', 'bảo vệ, giữ gìn', 'Vst', '我們應該愛護公共設施，不要隨便破壞。', 'wǒ men yīng gāi ài hù gōng gòng shè shī， bú yào suí biàn pò huài。', 'Chúng ta nên giữ gìn các công trình công cộng, đừng tùy tiện phá hoại.', 'dictionary_words', 1821) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '安慰', NULL, 'ānwèi', 'an ủi', 'V', '看到她哭了，朋友們都過來安慰她。', 'kàn dào tā kū le， péng yǒu men dōu guò lái ān wèi tā。', 'Thấy cô ấy khóc, bạn bè đều đến an ủi cô ấy.', 'dictionary_words', 1822) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '安裝', NULL, 'ānzhuāng', 'lắp đặt, lắp ráp', 'V', '師傅花了一個下午才把冷氣安裝好。', 'shī fù huā le yí gè xià wǔ cái bǎ lěng qì ān zhuāng hǎo。', 'Người thợ mất cả buổi chiều mới lắp xong máy lạnh.', 'dictionary_words', 1823) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '按', NULL, 'àn', 'nhấn, bấm, đè', 'V', '請按這個紅色按鈕就可以開機了。', 'qǐng àn zhè gè hóng sè àn niǔ jiù kě yǐ kāi jī le。', 'Xin hãy nhấn nút màu đỏ này là có thể khởi động máy.', 'dictionary_words', 1824) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '按時', NULL, 'ànshí', 'đúng hạn', 'Adv', '不管多忙，他每天都按時吃藥。', 'bù guǎn duō máng， tā měi tiān dōu àn shí chī yào。', 'Dù bận đến mấy, ngày nào anh ấy cũng uống thuốc đúng giờ.', 'dictionary_words', 1825) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '暗', NULL, 'àn', 'tối, tối tăm', 'Vs', '房間裡的燈壞了，變得很暗。', 'fáng jiān lǐ de dēng huài le， biàn de hěn àn。', 'Đèn trong phòng bị hỏng, trở nên rất tối.', 'dictionary_words', 1826) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '暗中', NULL, 'ànzhōng', 'trong bóng tối', 'Adv', '他一直暗中觀察那個陌生人的一舉一動。', 'tā yì zhí àn zhōng guān chá nà gè mò shēng rén de yì jǔ yí dòng。', 'Anh ấy vẫn luôn âm thầm quan sát mọi cử chỉ của người lạ đó.', 'dictionary_words', 1827) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '骯髒', NULL, 'āngzhāng', 'dơ bẩn', 'Vs', '這條巷子的地上到處都是骯髒的垃圾。', 'zhè tiáo xiàng zi de dì shàng dào chǔ dōu shì āng zāng de lā jī。', 'Mặt đất trong con hẻm này khắp nơi đều là rác bẩn.', 'dictionary_words', 1828) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拔', NULL, 'bá', 'nhổ, rút', 'V', '醫生小心地幫他拔掉那顆蛀牙。', 'yī shēng xiǎo xīn de bāng tā bá diào nà kē zhù yá。', 'Bác sĩ cẩn thận nhổ giúp anh ấy chiếc răng sâu đó.', 'dictionary_words', 1829) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '把握', NULL, 'băwò', 'cầm, nắm, nắm bắt', 'N', '這次考試他很有把握，一定能考好。', 'zhè cì kǎo shì tā hěn yǒu bǎ wò， yí dìng néng kǎo hǎo。', 'Kỳ thi này anh ấy rất tự tin, chắc chắn sẽ làm tốt.', 'dictionary_words', 1830) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '罷工', NULL, 'bàgōng', 'bãi công, đình công', 'Vi', '因為工資太低，工人們決定罷工抗議。', 'yīn wèi gōng zī tài dī， gōng rén men jué dìng bà gōng kàng yì。', 'Vì lương quá thấp, công nhân quyết định đình công phản đối.', 'dictionary_words', 1831) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '擺脫', NULL, 'băituō', 'thoát khỏi', 'V', '他花了好幾年才擺脫債務的困擾。', 'tā huā le hǎo jǐ nián cái bǎi tuō zhài wù de kùn rǎo。', 'Anh ấy mất mấy năm mới thoát khỏi cảnh nợ nần.', 'dictionary_words', 1832) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '敗', NULL, 'bài', 'thua, bại trận', 'Vp', '這場比賽我們隊以一分之差敗給對手。', 'zhè chǎng bǐ sài wǒ men duì yǐ yì fēn zhī chā bài gěi duì shǒu。', 'Trận đấu này đội chúng tôi thua đối thủ với cách biệt một điểm.', 'dictionary_words', 1833) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拜', NULL, 'bài', 'lạy, vái', 'V', '每逢初一，媽媽都會準備水果去廟裡拜神。', 'měi féng chū yī， mā ma dōu huì zhǔn bèi shuǐ guǒ qù miào lǐ bài shén。', 'Cứ đến mùng một, mẹ đều chuẩn bị trái cây đến chùa lạy thần.', 'dictionary_words', 1834) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拜拜', NULL, 'bàibai', 'cúi chào', 'Vi', '朋友們互相說了聲拜拜，就各自回家了。', 'péng yǒu men hù xiāng shuō le shēng bài bai， jiù gè zì huí jiā le。', 'Các bạn chào tạm biệt nhau rồi mỗi người về nhà.', 'dictionary_words', 1835) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拜訪', NULL, 'bàifăng', 'thăm viếng, thăm hỏi', 'V', '明天我打算去拜訪一位多年不見的老師。', 'míng tiān wǒ dǎ suàn qù bài fǎng yí wèi duō nián bú jiàn de lǎo shī。', 'Ngày mai tôi định đi thăm một người thầy đã nhiều năm không gặp.', 'dictionary_words', 1836) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拜年', NULL, 'bàinián', 'đi chúc tết', 'V-sep', '大年初一，全家人一起去外婆家拜年。', 'dà nián chū yī， quán jiā rén yì qǐ qù wài pó jia bài nián。', 'Mùng một Tết, cả nhà cùng đến nhà bà ngoại chúc Tết.', 'dictionary_words', 1837) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拜託', NULL, 'bàituō', 'nhờ vả', 'V', '拜託你幫我把這份文件送到辦公室。', 'bài tuō nǐ bāng wǒ bǎ zhè fèn wén jiàn sòng dào bàn gōng shì。', 'Nhờ bạn giúp tôi mang tài liệu này đến văn phòng.', 'dictionary_words', 1838) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '班', NULL, 'bān', 'lớp, ca, buổi làm', 'M', '他今天上晚班，要到十點才下班。', 'tā jīn tiān shàng wǎn bān， yào dào shí diǎn cái xià bān。', 'Hôm nay anh ấy làm ca tối, phải đến mười giờ mới tan làm.', 'dictionary_words', 1839) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '班長', NULL, 'bānzhăng', 'lớp trưởng', 'N', '老師選她當班長，因為她做事很負責。', 'lǎo shī xuǎn tā dāng bān zhǎng， yīn wèi tā zuò shì hěn fù zé。', 'Cô giáo chọn bạn ấy làm lớp trưởng vì bạn ấy làm việc rất có trách nhiệm.', 'dictionary_words', 1840) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '搬運', NULL, 'bānyùn', 'vận chuyển, vận tải', 'V', '工人正忙著把貨物搬運到卡車上。', 'gōng rén zhèng máng zhe bǎ huò wù bān yùn dào kǎ chē shàng。', 'Công nhân đang bận vận chuyển hàng hóa lên xe tải.', 'dictionary_words', 1841) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '拌', NULL, 'bàn', 'trộn, trộn lẫn', 'V', '媽媽用醬油和麻油把青菜拌一拌。', 'mā ma yòng jiàng yóu hé má yóu bǎ qīng cài bàn yi bàn。', 'Mẹ dùng xì dầu và dầu mè trộn đều rau xanh.', 'dictionary_words', 1842) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '半路', NULL, 'bànlù', 'nửa đường, giữa đường', 'N', '我們走到半路才發現忘了帶雨傘。', 'wǒ men zǒu dào bàn lù cái fā xiàn wàng le dài yǔ sǎn。', 'Chúng tôi đi đến giữa đường mới phát hiện quên mang ô.', 'dictionary_words', 1843) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '扮演', NULL, 'bànyăn', 'đóng vai, sắm vai', 'V', '她在這部電影裡扮演一位堅強的母親。', 'tā zài zhè bù diàn yǐng lǐ bàn yǎn yí wèi jiān qiáng de mǔ qīn。', 'Cô ấy đóng vai một người mẹ kiên cường trong bộ phim này.', 'dictionary_words', 1844) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '傍晚', NULL, 'bāngwăn', 'chạng vạng, chập tối', 'N', '我們約好傍晚在公園門口見面。', 'wǒ men yuē hǎo bàng wǎn zài gōng yuán mén kǒu jiàn miàn。', 'Chúng tôi hẹn gặp nhau lúc chập tối ở cổng công viên.', 'dictionary_words', 1845) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '磅', NULL, 'bàng', 'pound (đơn vị cân nặng)', 'M', '這袋麵粉重五磅。', 'zhè dài miàn fěn zhòng wǔ bàng。', 'Túi bột mì này nặng năm pound.', 'dictionary_words', 1846) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '棒', NULL, 'bàng', 'gậy, thỏi', 'M', '老師拿著一根長棒指著地圖。', 'lǎo shī ná zhe yì gēn cháng bàng zhǐ zhe dì tú。', 'Thầy giáo cầm một cây gậy dài chỉ vào bản đồ.', 'dictionary_words', 1847) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '棒子', NULL, 'bàngzi', 'cây gậy', 'N', '他撿起地上的棒子趕走了野狗。', 'tā jiǎn qǐ dì shàng de bàng zi gǎn zǒu le yě gǒu。', 'Anh ấy nhặt cây gậy dưới đất lên đuổi con chó hoang đi.', 'dictionary_words', 1848) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '包括', NULL, 'bāokuò', 'bao gồm', 'Vst', '這個價錢包括早餐和晚餐。', 'zhè gè jià qián bāo kuò zǎo cān hé wǎn cān。', 'Giá này bao gồm cả bữa sáng và bữa tối.', 'dictionary_words', 1849) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '包裝', NULL, 'bāozhuāng', 'bao bì', 'N', '這款產品的包裝設計得很精美。', 'zhè kuǎn chǎn pǐn de bāo zhuāng shè jì de hěn jīng měi。', 'Bao bì của sản phẩm này được thiết kế rất tinh xảo.', 'dictionary_words', 1850) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '包裝', NULL, 'bāozhuāng', 'đóng gói', 'V', '店員細心地把禮物包裝好。', 'diàn yuán xì xīn de bǎ lǐ wù bāo zhuāng hǎo。', 'Nhân viên bán hàng đóng gói món quà rất cẩn thận.', 'dictionary_words', 1851) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保', NULL, 'băo', 'giữ, gìn giữ', 'V', '這種天氣，能不能準時到達都很難保。', 'zhè zhǒng tiān qì， néng bu néng zhǔn shí dào dá dōu hěn nán bǎo。', 'Thời tiết thế này, có đến đúng giờ được hay không cũng khó mà đảm bảo.', 'dictionary_words', 1852) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保持', NULL, 'băochí', 'duy trì, giữ nguyên', 'V', '每天運動可以幫助你保持身材。', 'měi tiān yùn dòng kě yǐ bāng zhù nǐ bǎo chí shēn cái。', 'Tập thể dục mỗi ngày có thể giúp bạn duy trì vóc dáng.', 'dictionary_words', 1853) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保存', NULL, 'băocún', 'bảo tồn', 'V', '這些珍貴的照片都被完整地保存下來了。', 'zhè xiē zhēn guì de zhào piàn dōu bèi wán zhěng de bǎo cún xià lái le。', 'Những bức ảnh quý giá này đều được bảo tồn nguyên vẹn.', 'dictionary_words', 1854) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保留', NULL, 'băoliú', 'bảo lưu, giữ nguyên', 'V', '對於這個決定，他保留了自己的意見。', 'duì yú zhè gè jué dìng， tā bǎo liú le zì jǐ de yì jiàn。', 'Đối với quyết định này, anh ấy vẫn bảo lưu ý kiến riêng của mình.', 'dictionary_words', 1855) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保衛', NULL, 'băowèi', 'bảo vệ, che chở', 'V', '士兵們用生命保衛自己的國家。', 'shì bīng men yòng shēng mìng bǎo wèi zì jǐ de guó jiā。', 'Các chiến sĩ dùng cả tính mạng để bảo vệ đất nước mình.', 'dictionary_words', 1856) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保障', NULL, 'băozhàng', 'vật bảo đảm, đồ bảo hộ', 'N', '穩定的收入是生活的重要保障。', 'wěn dìng de shōu rù shì shēng huó de zhòng yào bǎo zhàng。', 'Thu nhập ổn định là sự bảo đảm quan trọng cho cuộc sống.', 'dictionary_words', 1857) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '保障', NULL, 'băozhàng', 'bảo đảm, bảo hộ', 'V', '法律保障每個人的基本人權。', 'fǎ lǜ bǎo zhàng měi gè rén de jī běn rén quán。', 'Pháp luật bảo đảm quyền con người cơ bản của mỗi người.', 'dictionary_words', 1858) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '寶寶', NULL, 'băobao', 'cục cưng, bé cưng', 'N', '她一邊哄寶寶睡覺，一邊輕輕唱歌。', 'tā yì biān hǒng bǎo bǎo shuì jiào， yì biān qīng qīng chàng gē。', 'Chị ấy vừa dỗ bé ngủ vừa khe khẽ hát.', 'dictionary_words', 1859) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
