INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '奔跑', NULL, 'bēnpăo', 'chạy nhanh', 'Vi', '孩子們在草地上開心地奔跑。', 'hái zi men zài cǎo dì shàng kāi xīn de bēn pǎo。', 'Bọn trẻ chạy nhảy vui vẻ trên bãi cỏ.', 'dictionary_words', 1872) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '本來', NULL, 'běnlái', 'vốn có, lúc đầu', 'Vs-attr', '這件事本來就跟你沒有關係。', 'zhè jiàn shì běn lái jiù gēn nǐ méi yǒu guān xì。', 'Chuyện này vốn dĩ chẳng liên quan gì đến bạn cả.', 'dictionary_words', 1873) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '本身', NULL, 'běnshēn', 'bản thân', 'N', '這個問題本身就很複雜，很難有標準答案。', 'zhè gè wèn tí běn shēn jiù hěn fù zá， hěn nán yǒu biāo zhǔn dá àn。', 'Bản thân vấn đề này đã rất phức tạp, khó mà có đáp án chuẩn.', 'dictionary_words', 1874) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '本土', NULL, 'běntŭ', 'quê hương, mảnh đất này', 'N', '這家公司近年來積極開發本土市場。', 'zhè jiā gōng sī jìn nián lái jī jí kāi fā běn tǔ shì chǎng。', 'Những năm gần đây công ty này tích cực khai thác thị trường bản địa.', 'dictionary_words', 1875) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '笨重', NULL, 'bènzhòng', 'cồng kềnh, to lớn', 'Vs', '這台舊冰箱又笨重又占空間。', 'zhè tái jiù bīng xiāng yòu bèn zhòng yòu zhàn kōng jiān。', 'Chiếc tủ lạnh cũ này vừa cồng kềnh vừa chiếm diện tích.', 'dictionary_words', 1876) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '比方', NULL, 'bĭfāng', 'ví, so bì', 'N', '我打個比方，你就明白了。', 'wǒ dǎ gè bǐ fāng， nǐ jiù míng bái le。', 'Để tôi ví dụ thế này, bạn sẽ hiểu ngay.', 'dictionary_words', 1877) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '比較', NULL, 'bĭjiào', 'tương đối, khá', 'V', '今天的天氣比較涼快。', 'jīn tiān de tiān qì bǐ jiào liáng kuài。', 'Thời tiết hôm nay tương đối mát mẻ.', 'dictionary_words', 1878) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '比例', NULL, 'bĭlì', 'tỉ lệ', 'N', '這次調查中，女性的比例比男性高。', 'zhè cì diào chá zhōng， nǚ xìng de bǐ lì bǐ nán xìng gāo。', 'Trong cuộc khảo sát này, tỉ lệ nữ giới cao hơn nam giới.', 'dictionary_words', 1879) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '彼此', NULL, 'bĭcĭ', 'lẫn nhau', 'N', '雖然意見不同，我們還是要彼此尊重。', 'suī rán yì jiàn bù tóng， wǒ men hái shì yào bǐ cǐ zūn zhòng。', 'Dù ý kiến khác nhau, chúng ta vẫn phải tôn trọng lẫn nhau.', 'dictionary_words', 1880) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '筆記', NULL, 'bĭjì', 'ghi chép', 'N', '上課的時候，她總是認真做筆記。', 'shàng kè de shí hòu， tā zǒng shì rèn zhēn zuò bǐ jì。', 'Trong giờ học, cô ấy luôn chăm chỉ ghi chép bài.', 'dictionary_words', 1881) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '筆試', NULL, 'bĭshì', 'cuộc thi viết', 'N', '這次應徵需要先通過筆試才能進入面試。', 'zhè cì yìng zhēng xū yào xiān tōng guò bǐ shì cái néng jìn rù miàn shì。', 'Lần tuyển dụng này cần phải qua bài thi viết trước rồi mới được vào phỏng vấn.', 'dictionary_words', 1882) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '筆試', NULL, 'bĭshì', 'thi viết', 'Vi', '明天要筆試，他今晚得好好複習。', 'míng tiān yào bǐ shì， tā jīn wǎn děi hǎo hǎo fù xí。', 'Ngày mai phải thi viết, tối nay anh ấy phải ôn tập cho kỹ.', 'dictionary_words', 1883) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '閉', NULL, 'bì', 'đóng, khép, bịt', 'Vi', '醫生請他閉上眼睛檢查視力。', 'yī shēng qǐng tā bì shàng yǎn jīng jiǎn chá shì lì。', 'Bác sĩ yêu cầu anh ấy nhắm mắt lại để kiểm tra thị lực.', 'dictionary_words', 1884) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '必須', NULL, 'bìxū', 'phải, nhất định', 'Vs-attr', '進入實驗室之前必須先戴上口罩和手套。', 'jìn rù shí yàn shì zhī qián bì xū xiān dài shàng kǒu zhào hé shǒu tào。', 'Trước khi vào phòng thí nghiệm nhất định phải đeo khẩu trang và găng tay.', 'dictionary_words', 1885) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '必要', NULL, 'bìyào', 'cần thiết, thiết yếu', 'N', '我覺得沒有必要為了這種小事吵架。', 'wǒ jué de méi yǒu bì yào wèi le zhè zhǒng xiǎo shì chǎo jià。', 'Tôi thấy không cần thiết phải cãi nhau vì chuyện nhỏ nhặt như vậy.', 'dictionary_words', 1886) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '編', NULL, 'biān', 'bện, đan, thắt', 'V', '奶奶正在用竹子編一個籃子。', 'nǎi nai zhèng zài yòng zhú zi biān yí gè lán zi。', 'Bà đang dùng tre đan một cái giỏ.', 'dictionary_words', 1887) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '扁', NULL, 'biǎn', 'dẹt, dẹp', 'VS', '這顆球被壓得扁扁的，沒辦法用了。', 'zhè kē qiú bèi yā de biǎn biǎn de， méi bàn fǎ yòng le。', 'Quả bóng này bị đè dẹp lép, không dùng được nữa.', 'dictionary_words', 1888) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
