INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '便利', NULL, 'biànlì', 'tiện lợi', 'Vs', '這附近有捷運站，交通非常便利。', 'zhè fù jìn yǒu jié yùn zhàn， jiāo tōng fēi cháng biàn lì。', 'Gần đây có ga tàu điện ngầm, giao thông rất tiện lợi.', 'dictionary_words', 1890) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '變動', NULL, 'biàndòng', 'biến động, thay đổi', 'N', '這次組織的變動讓不少員工感到不安。', 'zhè cì zǔ zhī de biàn dòng ràng bù shǎo yuán gōng gǎn dào bù ān。', 'Sự biến động tổ chức lần này khiến không ít nhân viên cảm thấy bất an.', 'dictionary_words', 1891) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '變動', NULL, 'biàndòng', 'thay đổi, biến đổi', 'Vp', '由於天氣關係，行程可能會有所變動。', 'yóu yú tiān qì guān xì， xíng chéng kě néng huì yǒu suǒ biàn dòng。', 'Do vấn đề thời tiết, lịch trình có thể sẽ có sự thay đổi.', 'dictionary_words', 1892) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '標題', NULL, 'biāotí', 'đầu đề, tiêu đề', 'N', '這篇文章的標題吸引了很多讀者。', 'zhè piān wén zhāng de biāo tí xī yǐn le hěn duō dú zhě。', 'Tiêu đề của bài viết này đã thu hút rất nhiều độc giả.', 'dictionary_words', 1893) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '標誌', NULL, 'biāozhì', 'ký hiệu', 'N', '路口豎立著一個禁止左轉的標誌。', 'lù kǒu shù lì zhe yí gè jìn zhǐ zuǒ zhuǎn de biāo zhì。', 'Ở ngã tư dựng một biển báo cấm rẽ trái.', 'dictionary_words', 1894) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '表格', NULL, 'biăogé', 'bảng, bảng hiệu', 'N', '請填好這張表格再交給櫃檯。', 'qǐng tián hǎo zhè zhāng biǎo gé zài jiāo gěi guì tái。', 'Xin điền xong tờ biểu mẫu này rồi nộp lại cho quầy lễ tân.', 'dictionary_words', 1895) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '表情', NULL, 'biăoqíng', 'biểu cảm', 'N', '從她的表情就能看出她很失望。', 'cóng tā de biǎo qíng jiù néng kàn chū tā hěn shī wàng。', 'Nhìn biểu cảm của cô ấy là biết ngay cô ấy rất thất vọng.', 'dictionary_words', 1896) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '表揚', NULL, 'biăoyáng', 'khen, biểu dương', 'V', '校長在朝會上公開表揚了那位拾金不昧的學生。', 'xiào zhǎng zài cháo huì shàng gōng kāi biǎo yáng le nà wèi shí jīn bú mèi de xué shēng。', 'Hiệu trưởng đã công khai khen thưởng học sinh nhặt được của rơi trả lại người mất đó trong buổi chào cờ.', 'dictionary_words', 1897) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '丙', NULL, 'bǐng', 'hạng C, loại thứ ba', 'N', '這次評鑑他的部門被評為丙等。', 'zhè cì píng jiàn tā de bù mén bèi píng wéi bǐng děng。', 'Lần đánh giá này bộ phận của anh ấy bị xếp hạng C.', 'dictionary_words', 1898) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '並', NULL, 'bìng', 'hợp lại, nhập lại', 'Adv', '事情並沒有你想的那麼簡單。', 'shì qíng bìng méi yǒu nǐ xiǎng de nà me jiǎn dān。', 'Sự việc hoàn toàn không đơn giản như bạn nghĩ.', 'dictionary_words', 1899) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '撥', NULL, 'bō', 'đẩy, gẩy', 'V', '請撥這個號碼跟客服聯絡。', 'qǐng bō zhè gè hào mǎ gēn kè fú lián luò。', 'Xin hãy bấm số này để liên hệ với bộ phận chăm sóc khách hàng.', 'dictionary_words', 1900) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '波動', NULL, 'bōdòng', 'chập chờn, không ổn định', 'Vi', '最近股市波動很大，投資人都很緊張。', 'zuì jìn gǔ shì bō dòng hěn dà， tóu zī rén dōu hěn jǐn zhāng。', 'Gần đây thị trường chứng khoán biến động rất mạnh, các nhà đầu tư đều rất lo lắng.', 'dictionary_words', 1901) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '玻璃', NULL, 'bōli', 'thủy tinh', 'N', '小心，這個杯子是玻璃做的，很容易破。', 'xiǎo xīn， zhè gè bēi zi shì bō lí zuò de， hěn róng yì pò。', 'Cẩn thận, cái cốc này làm bằng thủy tinh, rất dễ vỡ.', 'dictionary_words', 1902) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '薄', NULL, 'bó', 'mỏng manh', 'Vs', '這家公司靠著薄利多銷的方式擴大市場。', 'zhè jiā gōng sī kào zhe bó lì duō xiāo de fāng shì kuò dà shì chǎng。', 'Công ty này mở rộng thị trường bằng cách lãi ít bán nhiều.', 'dictionary_words', 1903) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '薄弱', NULL, 'bóruò', 'bạc nhược, yếu kém', 'Vs', '他的意志力比較薄弱，遇到挫折容易放棄。', 'tā de yì zhì lì bǐ jiào bó ruò， yù dào cuò zhé róng yì fàng qì。', 'Ý chí của anh ấy khá yếu, gặp khó khăn là dễ bỏ cuộc.', 'dictionary_words', 1904) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '伯父', NULL, 'bófù', 'bác trai', 'N', '我的伯父是一位退休的中學老師。', 'wǒ de bó fù shì yí wèi tuì xiū de zhōng xué lǎo shī。', 'Bác trai của tôi là một giáo viên trung học đã nghỉ hưu.', 'dictionary_words', 1905) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
