INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '補助', NULL, 'bŭzhù', 'giúp đỡ', 'V', '學校決定補助清寒學生的午餐費用。', 'xué xiào jué dìng bǔ zhù qīng hán xué shēng de wǔ cān fèi yòng。', 'Nhà trường quyết định trợ cấp tiền ăn trưa cho học sinh nghèo.', 'dictionary_words', 1912) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '步', NULL, 'bù', 'bước chân', 'M', '他往前走了幾步，就停下來了。', 'tā wǎng qián zǒu le jǐ bù， jiù tíng xià lái le。', 'Anh ấy đi về phía trước vài bước rồi dừng lại.', 'dictionary_words', 1913) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '不大', NULL, 'bùdà', 'vừa phải', 'Adv', '這道菜不大辣，你可以放心吃。', 'zhè dào cài bú dà là， nǐ kě yǐ fàng xīn chī。', 'Món này không cay lắm, bạn có thể yên tâm ăn.', 'dictionary_words', 1914) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '不安', NULL, 'bùān', 'bất an, bất ổn', 'Vs', '考試結果還沒公布，他心裡感到很不安。', 'kǎo shì jié guǒ hái méi gōng bù， tā xīn lǐ gǎn dào hěn bù ān。', 'Kết quả thi chưa công bố, trong lòng anh ấy cảm thấy rất bất an.', 'dictionary_words', 1915) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
