INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '不顧', NULL, 'bùgù', 'không quan tâm', 'Vst', '他不顧大家的反對，堅持辭職去創業。', 'tā bú gù dà jiā de fǎn duì， jiān chí cí zhí qù chuàng yè。', 'Anh ấy bất chấp sự phản đối của mọi người, kiên quyết nghỉ việc để khởi nghiệp.', 'dictionary_words', 1920) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
