INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '潮溼/濕', NULL, 'cháoshī', 'ẩm ướt', 'Vs', '梅雨季節，衣服常常曬不乾，房間也很潮溼。', 'méi yǔ jì jié， yī fu cháng cháng shài bù gān， fáng jiān yě hěn cháo shī。', 'Vào mùa mưa phùn, quần áo thường phơi không khô, phòng cũng rất ẩm ướt.', 'dictionary_words', 1977) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
