INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'other', 'Khác', '✨', '崇高', NULL, 'chónggāo', 'cao thượng, cao quý', 'Vs', '他為了理想犧牲自己，精神十分崇高。', 'tā wèi le lǐ xiǎng xī shēng zì jǐ， jīng shén shí fēn chóng gāo。', 'Anh ấy vì lý tưởng mà hy sinh bản thân, tinh thần vô cùng cao thượng.', 'dictionary_words', 2004) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
