INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '彈', NULL, 'tán', 'đánh, gảy (đàn)', 'V', '她從小就學彈鋼琴，現在彈得非常好。', 'tā cóng xiǎo jiù xué tán gāng qín, xiàn zài tán de fēi cháng hǎo。', 'Cô ấy học đàn piano từ nhỏ, bây giờ đánh rất giỏi.', 'dictionary_words', 95) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
