INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '逃避', NULL, 'táobì', 'trốn tránh', 'V', '遇到問題應該面對，不應該一直逃避。', 'yù dào wèn tí yīng gāi miàn duì, bù yīng gāi yì zhí táo bì。', 'Gặp vấn đề nên đối mặt, không nên cứ mãi trốn tránh.', 'dictionary_words', 97) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
