INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '妥當', NULL, 'tuǒdang', 'thỏa đáng', 'Vs', '這樣安排比較妥當，大家都沒有意見。', 'zhè yàng ān pái bǐ jiào tuǒ dang, dà jiā dōu méi yǒu yì jiàn。', 'Sắp xếp như vậy khá thỏa đáng, mọi người đều không có ý kiến gì.', 'dictionary_words', 99) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '下棋', NULL, 'xiàqí', 'chơi cờ, đánh cờ', 'V-sep', '爺爺每天下午都跟鄰居下棋。', 'yé ye měi tiān xià wǔ dōu gēn lín jū xià qí。', 'Ông nội mỗi buổi chiều đều chơi cờ với hàng xóm.', 'dictionary_words', 100) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '享有', NULL, 'xiăngyŏu', 'được hưởng (quyền lợi…)', 'Vst', '正式員工可以享有完整的福利。', 'zhèng shì yuán gōng kě yǐ xiǎng yǒu wán zhěng de fú lì。', 'Nhân viên chính thức có thể được hưởng đầy đủ phúc lợi.', 'dictionary_words', 101) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '把', NULL, 'bă', 'cán, quai, tay cầm', 'M', '桌上放著一把剪刀和一把尺。', 'zhuō shàng fàng zhe yì bǎ jiǎn dāo hé yì bǎ chǐ。', 'Trên bàn để một cái kéo và một cây thước.', 'dictionary_words', 102) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '包裹', NULL, 'bāoguǒ', 'gói, kiện hàng', 'N', '郵差今天送來一個很大的包裹。', 'yóu chāi jīn tiān sòng lái yí gè hěn dà de bāo guǒ。', 'Hôm nay người đưa thư mang đến một kiện hàng rất lớn.', 'dictionary_words', 103) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '報警', NULL, 'bàojĭng', 'báo nguy, báo cảnh sát', 'V-sep', '發現有人闖入，鄰居立刻報警。', 'fā xiàn yǒu rén chuǎng rù， lín jū lì kè bào jǐng。', 'Phát hiện có người đột nhập, hàng xóm lập tức báo cảnh sát.', 'dictionary_words', 104) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '比', NULL, 'bĭ', 'so sánh, so đo', 'V', '這兩件衣服的價錢差不多，你可以比一比。', 'zhè liǎng jiàn yī fu de jià qián chà bù duō， nǐ kě yǐ bǐ yi bǐ。', 'Giá của hai chiếc áo này gần bằng nhau, bạn có thể so sánh thử.', 'dictionary_words', 105) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '比方(說)', NULL, 'bĭfāng(shūo)', 'so sánh với', 'Vst', '有些水果，比方說榴槤，味道很特別。', 'yǒu xiē shuǐ guǒ， bǐ fāng shuō liú lián， wèi dào hěn tè bié。', 'Có một số loại trái cây, ví dụ như sầu riêng, có mùi vị rất đặc biệt.', 'dictionary_words', 106) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '比較', NULL, 'bĭjiào', 'so sánh', 'N', '老師要我們做一個中西文化的比較。', 'lǎo shī yào wǒ men zuò yí gè zhōng xī wén huà de bǐ jiào。', 'Thầy giáo yêu cầu chúng tôi làm một bài so sánh văn hóa Đông Tây.', 'dictionary_words', 107) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '不當', NULL, 'bùdàng', 'không thích đáng', 'Vs', '他因為言論不當而被公司處分。', 'tā yīn wèi yán lùn bú dàng ér bèi gōng sī chǔ fèn。', 'Anh ấy vì phát ngôn không thỏa đáng mà bị công ty kỷ luật.', 'dictionary_words', 108) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'law', 'Hành chính & Luật pháp', '⚖️', '裁判', NULL, 'cáipàn', 'phán xử, xét xử', 'N', '裁判吹了哨子，宣布比賽結束。', 'cái pàn chuī le shào zi， xuān bù bǐ sài jié shù。', 'Trọng tài thổi còi, tuyên bố trận đấu kết thúc.', 'dictionary_words', 109) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
