INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'home-living', 'Nhà cửa & Đời sống', '🏠', '委屈', NULL, 'wěiqū', 'tủi thân', 'Vs', '被老闆誤會後，她覺得很委屈。', 'bèi lǎo bǎn wù huì hòu, tā jué de hěn wěi qū。', 'Sau khi bị ông chủ hiểu lầm, cô ấy cảm thấy rất tủi thân.', 'dictionary_words', 14) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'home-living', 'Nhà cửa & Đời sống', '🏠', '臥房', NULL, 'wòfáng', 'phòng ngủ', 'N', '這間房子有三個臥房，很適合一家人住。', 'zhè jiān fáng zi yǒu sān gè wò fáng, hěn shì hé yì jiā rén zhù。', 'Căn nhà này có ba phòng ngủ, rất thích hợp cho cả gia đình ở.', 'dictionary_words', 15) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'home-living', 'Nhà cửa & Đời sống', '🏠', '舞廳', NULL, 'wŭtīng', 'phòng nhảy', 'N', '這家舞廳每週末都有現場樂團演奏。', 'zhè jiā wǔ tīng měi zhōu mò dōu yǒu xiàn chǎng yuè tuán yǎn zòu。', 'Vũ trường này mỗi cuối tuần đều có ban nhạc biểu diễn trực tiếp.', 'dictionary_words', 16) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'home-living', 'Nhà cửa & Đời sống', '🏠', '備', NULL, 'bèi', 'chuẩn bị, phòng bị', 'V', '出門前記得備好雨具，以防下雨。', 'chū mén qián jì de bèi hǎo yǔ jù， yǐ fáng xià yǔ。', 'Trước khi ra ngoài nhớ chuẩn bị sẵn đồ che mưa, phòng khi trời mưa.', 'dictionary_words', 17) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
