INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'restaurant', 'Nhà hàng & Ăn uống', '🍽️', '天文', NULL, 'tiānwén', 'thiên văn', 'N', '弟弟對天文很感興趣，常常用望遠鏡看星星。', 'dì di duì tiān wén hěn gǎn xìng qù, cháng cháng yòng wàng yuǎn jìng kàn xīng xing。', 'Em trai rất hứng thú với thiên văn học, thường xuyên dùng kính viễn vọng ngắm sao.', 'dictionary_words', 41) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
