INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'restaurant', 'Nhà hàng & Ăn uống', '🍽️', '文憑', NULL, 'wénpíng', 'văn bằng', 'N', '現在找工作，文憑不再是唯一的條件。', 'xiàn zài zhǎo gōng zuò, wén píng bú zài shì wéi yī de tiáo jiàn。', 'Bây giờ tìm việc, bằng cấp không còn là điều kiện duy nhất nữa.', 'dictionary_words', 44) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
