INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'health', 'Y tế & Sức khỏe', '🩺', '悲痛', NULL, 'bēitòng', 'bi thương, đau buồn', 'Vs', '得知老師去世的消息，學生們都非常悲痛。', 'dé zhī lǎo shī qù shì de xiāo xī， xué shēng men dōu fēi cháng bēi tòng。', 'Biết tin thầy giáo qua đời, học sinh ai nấy đều vô cùng đau buồn.', 'dictionary_words', 21) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
