INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'school', 'Học tập & Giáo dục', '📚', '探討', NULL, 'tàntăo', 'nghiên cứu thảo luận', 'V', '這篇論文主要探討氣候變遷對農業的影響。', 'zhè piān lùn wén zhǔ yào tàn tǎo qì hòu biàn qiān duì nóng yè de yǐng xiǎng。', 'Bài luận văn này chủ yếu thảo luận nghiên cứu về ảnh hưởng của biến đổi khí hậu đối với nông nghiệp.', 'dictionary_words', 28) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
