INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'school', 'Học tập & Giáo dục', '📚', '補課', NULL, 'bŭkè', 'học bù, dạy bù', 'V-sep', '因為颱風停課，老師安排星期六補課。', 'yīn wèi tái fēng tíng kè， lǎo shī ān pái xīng qī liù bǔ kè。', 'Vì bão nghỉ học, thầy giáo sắp xếp học bù vào thứ Bảy.', 'dictionary_words', 30) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
