INSERT INTO public.topic_vocabulary (level, topic_key, topic_label, topic_icon, hanzi, hanzi_variant, pinyin, vietnamese, pos, example_hanzi, example_pinyin, example_vietnamese, source, order_index) VALUES ('B2', 'relationships', 'Tình cảm & Quan hệ', '❤️', '想念', NULL, 'xiăngniàn', 'tưởng niệm, nhớ nhung', 'Vst', '出國留學後，他很想念家鄉的味道。', 'chū guó liú xué hòu, tā hěn xiǎng niàn jiā xiāng de wèi dào。', 'Sau khi ra nước ngoài du học, anh ấy rất nhớ hương vị quê nhà.', 'dictionary_words', 8) ON CONFLICT (level, topic_key, hanzi, pinyin) DO UPDATE SET topic_label = EXCLUDED.topic_label, topic_icon = EXCLUDED.topic_icon, vietnamese = EXCLUDED.vietnamese, pos = EXCLUDED.pos, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_vietnamese = EXCLUDED.example_vietnamese, order_index = EXCLUDED.order_index;
